global.initialValue:
{
  "kind": null,
  "provider": null,
  "providerOptions": null,
  "intent": {
    "generation": 0,
    "connectionId": null,
    "targetDriveId": null,
    "access": null,
    "source": null,
    "live": {
      "enabled": true,
      "every": {
        "value": 5,
        "unit": "MINUTES"
      }
    },
    "backfill": {
      "enabled": true,
      "batch": null,
      "items": [],
      "pinnedId": null
    },
    "archived": false
  },
  "resources": {
    "connectionId": null,
    "liveWorkflowId": null,
    "backfillWorkflowId": null,
    "pluggedItemId": null
  },
  "applied": null,
  "check": null,
  "checkRequest": null,
  "fixes": [],
  "runner": null
}

operations.schema:
input InitializeInput {
  kind: IntegrationKind!
  provider: String!
}

operations.reducer:
if (state.kind) throw new AlreadyInitializedError("The integration is set up already");
state.kind = action.input.kind;
state.provider = action.input.provider;

if (!state.kind) throw new NotInitializedError("Set up the integration first");
state.intent.access = action.input.access;
state.intent.generation += 1;

operations.schema:
input CalendarRefInput {
  id: String!
  name: String
}

input SetCalendarSourceInput {
  calendars: [CalendarRefInput!]!
  allOwned: Boolean!
}

operations.reducer:
if (state.kind !== "CALENDAR") throw new WrongKindError("Only a calendar integration has calendars");
state.intent.source = {
  calendars: action.input.allOwned
    ? []
    : action.input.calendars.map((c) => ({ id: c.id, name: c.name ?? null })),
  allOwned: action.input.allOwned,
};
state.intent.generation += 1;

operations.schema:
input SetEmailSourceInput {
  mailbox: String!
  address: String
  folders: [String!]!
}

operations.reducer:
if (state.kind !== "EMAIL") throw new WrongKindError("Only an email integration has a mailbox");
state.intent.source = {
  mailbox: action.input.mailbox,
  address: action.input.address ?? null,
  folders: action.input.folders,
};
state.intent.generation += 1;

operations.schema:
input BankAccountLinkInput {
  accountId: String!
  accountKey: String!
  bankAccountId: PHID!
  label: String
}

input SetTransactionsSourceInput {
  bankConnectionId: String!
  accounts: [BankAccountLinkInput!]!
}

operations.reducer:
if (state.kind !== "TRANSACTIONS") throw new WrongKindError("Only a transactions integration has bank accounts");
state.intent.source = {
  bankConnectionId: action.input.bankConnectionId,
  accounts: action.input.accounts.map((a) => ({
    accountId: a.accountId,
    accountKey: a.accountKey,
    bankAccountId: a.bankAccountId,
    label: a.label ?? null,
  })),
};
state.intent.generation += 1;

if (!state.kind) throw new NotInitializedError("Set up the integration first");
state.intent.live.enabled = action.input.enabled;
state.intent.generation += 1;

operations.schema:
input SetLiveIntervalInput {
  value: Int!
  unit: IntervalUnit!
}

operations.reducer:
if (!state.kind) throw new NotInitializedError("Set up the integration first");
if (!Number.isInteger(action.input.value) || action.input.value < 1) throw new InvalidIntervalError(`${action.input.value} is not a whole number of at least 1`);
state.intent.live.every = { value: action.input.value, unit: action.input.unit };
state.intent.generation += 1;

if (!state.kind) throw new NotInitializedError("Set up the integration first");
state.intent.backfill.enabled = action.input.enabled;
state.intent.generation += 1;

if (!state.kind) throw new NotInitializedError("Set up the integration first");
const i = action.input;
if (state.intent.backfill.items.some((b) => b.id === i.id)) throw new DuplicateBackfillIdError(`A backfill ${i.id} exists`);
if (!(Date.parse(i.from) < Date.parse(i.to)) || !Number.isInteger(i.stepSeconds) || i.stepSeconds < 60) throw new InvalidRangeError(`${i.from} to ${i.to} in ${i.stepSeconds} s slices`);
state.intent.backfill.items.push({
  id: i.id,
  label: i.label,
  documentType: i.documentType,
  documentId: null,
  request: { from: i.from, to: i.to, stepSeconds: i.stepSeconds, direction: i.direction ?? null },
});
state.intent.generation += 1;

if (!state.kind) throw new NotInitializedError("Set up the integration first");
const i = action.input;
if (state.intent.backfill.items.some((b) => b.id === i.id)) throw new DuplicateBackfillIdError(`A backfill ${i.id} exists`);
state.intent.backfill.items.push({
  id: i.id,
  label: i.label,
  documentType: i.documentType,
  documentId: i.documentId,
  request: null,
});
state.intent.generation += 1;

operations.schema:
input RemoveBackfillInput {
  "The backfill item; its document is the app's to delete"
  id: OID!
}

operations.reducer:
const items = state.intent.backfill.items;
const index = items.findIndex((b) => b.id === action.input.id);
if (index < 0) throw new UnknownBackfillError(`No backfill ${action.input.id}`);
items.splice(index, 1);
if (state.intent.backfill.pinnedId === action.input.id) state.intent.backfill.pinnedId = null;
state.intent.generation += 1;

operations.schema:
input RequestCheckInput {
  id: OID!
  requestedAt: DateTime!
  requestedBy: String
}

operations.reducer:
state.checkRequest = {
  id: action.input.id,
  requestedAt: action.input.requestedAt,
  requestedBy: action.input.requestedBy ?? null,
};

operations.schema:
input RecordRunnerInput {
  reactorId: String!
  label: String
}

input RecordResourcesInput {
  connectionId: PHID
  liveWorkflowId: PHID
  backfillWorkflowId: PHID
  pluggedItemId: OID
}

operations.reducer:
const i = action.input;
const r = state.resources;
if (i.connectionId) r.connectionId = i.connectionId;
if (i.liveWorkflowId) r.liveWorkflowId = i.liveWorkflowId;
if (i.backfillWorkflowId) r.backfillWorkflowId = i.backfillWorkflowId;
if (i.pluggedItemId) r.pluggedItemId = i.pluggedItemId;

operations.schema:
input RecordBackfillDocumentInput {
  "The backfill item"
  itemId: OID!
  "The backfill document the reconciler created for it"
  documentId: PHID!
}

operations.reducer:
const item = state.intent.backfill.items.find((b) => b.id === action.input.itemId);
if (!item) throw new BackfillNotFoundError(`No backfill ${action.input.itemId}`);
item.documentId = action.input.documentId;

const i = action.input;
state.check = {
  at: i.at,
  host: i.host ?? null,
  generation: i.generation,
  request: i.request ?? null,
  issues: i.issues.map((x) => ({
    code: x.code,
    severity: x.severity,
    subject: x.subject ?? null,
    message: x.message,
    fixable: x.fixable,
    since: x.since,
  })),
};
if (i.request && state.checkRequest?.id === i.request) state.checkRequest = null;
state.fixes = [
  ...i.fixes.map((f) => ({ at: f.at, code: f.code, subject: f.subject ?? null, message: f.message })),
  ...state.fixes,
].slice(0, 20);
// A commit for an older generation is ignored: the user changed something meanwhile.
if (i.committed && i.generation === state.intent.generation) {
  state.applied = { generation: i.generation, at: i.at, host: i.host ?? null };
}

operations.schema:
input ArchiveInput {
  "The empty-input workaround: ARCHIVE takes nothing"
  _: Boolean
}
